// TEMPORARY probe (pylib golden export, DESIGN.md section 4.4). Delete after use.
import 'dart:convert';
import 'dart:io';
import 'dart:math' as math;
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';
import 'package:polar_horizon/core/catalog.dart';
import 'package:polar_horizon/core/daily.dart';
import 'package:polar_horizon/core/dem.dart';
import 'package:polar_horizon/core/ephemeris.dart';
import 'package:polar_horizon/core/geo.dart';
import 'package:polar_horizon/core/horizon.dart';
import 'package:polar_horizon/core/horizon_compute.dart';
import 'package:polar_horizon/core/landing.dart';
import 'package:polar_horizon/core/metrics.dart';
import 'package:polar_horizon/core/ranking.dart';
import 'package:polar_horizon/core/score.dart';
import 'package:polar_horizon/core/shadow.dart';
import 'package:polar_horizon/core/summary.dart';
import 'package:polar_horizon/core/timeseries.dart';
import 'package:polar_horizon/core/visibility.dart';
import 'package:polar_horizon/state/light_engine.dart' show LightGrids, closeUpPx, closeUpRadiusM;

final outDir = Platform.environment['PYLIB_GOLDEN_OUT'] ?? '../pylib/tests/data/raw';
const day = 86400e3;

double ms(int y, int m, int d, [int h = 0]) => DateTime.utc(y, m, d, h).millisecondsSinceEpoch.toDouble();

Map<String, dynamic> scoreJson(ScoreBreakdown b) => {
      'power': b.power,
      'comms': b.comms,
      'both': b.both,
      'nightSurvival': b.nightSurvival,
      'outageTolerance': b.outageTolerance,
      'total': b.total,
    };

Map<String, dynamic>? winJson(LandingWindow? w) => w == null
    ? null
    : {
        'startIndex': w.startIndex,
        'samples': w.samples,
        'startMs': w.startMs,
        'endMs': w.endMs,
        'stepMs': w.stepMs,
        'sunPct': w.sunPct,
        'earthPct': w.earthPct,
        'bothPct': w.bothPct,
        'longestNightH': w.longestNightH,
        'longestOutageH': w.longestOutageH,
        'landsInSunlight': w.landsInSunlight,
        'landsWithEarth': w.landsWithEarth,
        'minSunFraction': w.minSunFraction,
        'minEarthFraction': w.minEarthFraction,
        'minPowerWm2': w.minPowerWm2,
        'halfSunHours': w.halfSunHours,
        'marginDeg': w.marginDeg,
        'touchdownSunMarginDeg': w.touchdownSunMarginDeg,
        'touchdownEarthMarginDeg': w.touchdownEarthMarginDeg,
        'fullFit': w.fullFit,
        'score': scoreJson(w.score),
      };

Map<String, dynamic>? planJson(LandingPlan? p) => p == null
    ? null
    : {
        'status': p.status.name,
        'missionDays': p.missionDays,
        'missionMs': p.missionMs,
        'stepMs': p.stepMs,
        'candidates': p.candidates,
        'periodDays': p.periodDays,
        'daysAvailable': p.daysAvailable,
        'notBeforeCut': p.notBeforeCut,
        'notBeforeMs': p.notBeforeMs,
        'suggested': winJson(p.suggested),
        'spanStartMs': p.spanStartMs,
        'spanEndMs': p.spanEndMs,
        'spanStartIndex': p.spanStartIndex,
        'spanEndIndex': p.spanEndIndex,
        'slackH': p.slackH,
        'tight': p.tight,
        'peak': winJson(p.peak),
        'nextSpanStartMs': p.nextSpanStartMs,
        'landingRuleRelaxed': p.landingRuleRelaxed,
        'longestBothRunDays': p.longestBothRunDays,
        'longestBothRunTruncated': p.longestBothRunTruncated,
        'longestBothRunAtEnd': p.longestBothRunAtEnd,
        'isFullFit': p.isFullFit,
        'hasSpan': p.hasSpan,
        'longestFitDays': p.longestFitDays,
      };

Map<String, dynamic> metricsJson(SiteMetrics m) => {
      'n': m.n,
      'stepHours': m.stepHours,
      'pctSunlit': m.pctSunlit,
      'pctEarth': m.pctEarth,
      'pctBoth': m.pctBoth,
      'pctDsn': m.pctDsn,
      'meanPowerWm2': m.meanPowerWm2,
      'energyKWhM2': m.energyKWhM2,
      'longestSun': m.longestSun?.toJson(),
      'longestDark': m.longestDark?.toJson(),
      'longestEarth': m.longestEarth?.toJson(),
      'longestEarthOutage': m.longestEarthOutage?.toJson(),
      'longestBoth': m.longestBoth?.toJson(),
      'bothWindowCount': m.bothWindowCount,
      'longestSunHours': m.longestSunHours,
      'longestDarkHours': m.longestDarkHours,
      'longestEarthOutageHours': m.longestEarthOutageHours,
      'longestBothHours': m.longestBothHours,
    };

String dayIso(DateTime d) =>
    '${d.year.toString().padLeft(4, '0')}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';

/// Non-finite doubles are not JSON: emit them as bare NaN / Infinity tokens (Python's json reads them).
Object? sanitize(Object? x) {
  if (x is double && !x.isFinite) return x.isNaN ? '__NaN__' : (x > 0 ? '__Infinity__' : '__-Infinity__');
  if (x is Map) return {for (final e in x.entries) e.key as String: sanitize(e.value)};
  if (x is List) return [for (final v in x) sanitize(v)];
  return x;
}

String encode(Object o) => const JsonEncoder.withIndent(null)
    .convert(sanitize(o))
    .replaceAll('"__NaN__"', 'NaN')
    .replaceAll('"__-Infinity__"', '-Infinity')
    .replaceAll('"__Infinity__"', 'Infinity');

class Case {
  final String key, siteId;
  final double lat, lon, terrainHeightM, h, t0, t1;
  final HorizonMask mask;
  final SeriesOptions opts;
  final Map<String, dynamic> extra;
  Case(this.key, this.siteId, this.lat, this.lon, this.terrainHeightM, this.h, this.t0, this.t1, this.mask, this.opts,
      [this.extra = const {}]);
}

void main() {
  final mapMeta = (jsonDecode(File('assets/data/map/map.json').readAsStringSync()) as Map<String, dynamic>)['dem'] as Map;
  final dem = PolarGrid.decodePlanarSplit(
      File('assets/data/map/dem_400m.bin.gz').readAsBytesSync(), mapMeta['size'] as int, (mapMeta['pxM'] as num).toDouble());
  final catalog =
      SiteCatalog.parse(File('assets/data/sites.json').readAsStringSync(), File('assets/data/horizons.json').readAsStringSync());
  late Ephemeris eph;

  setUpAll(() async {
    final repo = EphemerisRepository((p) async => Uint8List.fromList(await File('assets/data/$p').readAsBytes()));
    final man = await repo.manifest();
    // the whole bundled coverage (start 2025-01-01), like lunarhorizon CompactEphemeris.bundled()
    eph = await repo.range(man.startUnixMs.toDouble(), man.endUnixMs.toDouble());
    Directory(outDir).createSync(recursive: true);
  });

  test('export golden_plan', () {
    const customLat = -85.98, customLon = -0.26;
    final coarse = computeCoarseHorizon(dem, customLat, customLon, observerHeightsM: const [2.0, 10.0]);
    Case preset(String key, String id, double h, double t0, double t1, SeriesOptions o) {
      final s = catalog.byId(id);
      return Case(key, id, s.lat, s.lon, s.terrainHeightM, h, t0, t1, catalog.mask(id, h)!,
          o.copyWith(stepMs: SeriesOptions.autoStepMs(t1 - t0)));
    }

    final cases = [
      preset('case1', 'derosa2012-sr1-shackleton-rim', 2.0, ms(2027, 1, 1), ms(2027, 3, 1), const SeriesOptions()),
      preset('case2', 'derosa2012-mp1-malapert-peak', 10.0, ms(2027, 1, 1), ms(2028, 1, 1),
          const SeriesOptions(requireDsn: true)),
      preset('case3', 'artemis3-haworth', 2.0, ms(2026, 6, 1), ms(2026, 9, 1),
          const SeriesOptions(sunCriterion: SunCriterion.center, earthCriterion: EarthCriterion.anyPart)),
      Case('case4', 'custom', customLat, customLon, coarse.siteHeightM, 2.0, ms(2027, 1, 1), ms(2027, 2, 1),
          coarse.masks[2.0]!, SeriesOptions(stepMs: SeriesOptions.autoStepMs(ms(2027, 2, 1) - ms(2027, 1, 1)))),
      preset('case5', 'derosa2012-sr1-shackleton-rim', 2.0, ms(2027, 1, 1), ms(2027, 1, 4), const SeriesOptions()),
    ];
    // case 5 must be case 1's first 3 days: same step as case 1
    expect(cases[4].opts.stepMs, cases[0].opts.stepMs);

    final out = <String, dynamic>{
      'ephemerisStartMs': eph.startUnixMs,
      'ephemerisStepMs': eph.stepMs,
      'ephemerisCount': eph.count,
      'cases': <String, dynamic>{},
    };
    final metricsByCase = <String, (String, SiteMetrics)>{};
    for (final c in cases) {
      final obs = Observer(c.lat, c.lon, c.terrainHeightM + c.h);
      final s = computeSeries(eph, obs, c.mask, c.t0, c.t1, c.opts);
      var sSun = 0, sEarth = 0, sBoth = 0;
      var pSum = 0.0;
      for (var i = 0; i < s.n; i++) {
        if (s.flags[i] & 1 != 0) sSun++;
        if (s.flags[i] & 2 != 0) sEarth++;
        if (s.flags[i] & 4 != 0) sBoth++;
        pSum += s.power[i];
      }
      final idx = c.key == 'case5' ? [for (var i = 0; i < s.n; i++) i] : [for (var i = 0; i < s.n; i += 97) i];
      List<double> pick(Float64List a) => [for (final i in idx) a[i]];
      final m = computeMetrics(s);
      if (c.key != 'case5') metricsByCase[c.key] = (c.siteId, m);
      final days = dailySummaries(s);
      final ns = nextStretch(s, c.t0 + 10 * day);
      final goals = <String, dynamic>{};
      for (final g in Goal.values) {
        final w = weightsFor(g);
        final plans = <String, dynamic>{};
        for (final md in const [1, 7, 14, 30]) {
          final p = bestLandingWindow(s, md, w);
          plans['$md'] = {
            'plan': planJson(p),
            'nextFullFit': planJson(nextFullFit(s, p, w)),
          };
        }
        final nb = c.t0 + 5 * day;
        final pnb = bestLandingWindow(s, 14, w, notBeforeMs: nb);
        final m14 = missionSamples(14, s.stepMs);
        final at = <String, dynamic>{};
        if (m14 <= s.n) {
          for (final a in {0, s.n ~/ 2 <= s.n - m14 ? s.n ~/ 2 : 0, s.n - m14}) {
            at['$a'] = winJson(landingWindowAt(s, 14, w, a));
          }
        }
        goals[g.name] = {
          'weights': {'power': w.power, 'both': w.both},
          'score': scoreJson(score(m, w)),
          'formulaText': formulaText(w),
          'landing': plans,
          'notBefore14': {'notBeforeMs': nb, 'plan': planJson(pnb)},
          'landingWindowAt14': at,
        };
      }
      out['cases'][c.key] = {
        'siteId': c.siteId,
        'lat': c.lat,
        'lon': c.lon,
        'terrainHeightM': c.terrainHeightM,
        'observerHeightM': c.h,
        'startMs': c.t0,
        'endMs': c.t1,
        'options': {
          'stepMs': c.opts.stepMs,
          'sunCriterion': c.opts.sunCriterion.name,
          'earthCriterion': c.opts.earthCriterion.name,
          'requireDsn': c.opts.requireDsn,
        },
        'maskSource': c.mask.source,
        'maskApproximate': c.mask.approximate,
        'n': s.n,
        't0Ms': s.t0Ms,
        'stepMs': s.stepMs,
        'flagsB64': base64Encode(s.flags),
        'dsnB64': base64Encode(s.dsn),
        'sumSun': sSun,
        'sumEarth': sEarth,
        'sumBoth': sBoth,
        'sumPower': pSum,
        'sampleIndices': idx,
        'samples': {
          'sunAz': pick(s.sunAz),
          'sunEl': pick(s.sunEl),
          'sunHz': pick(s.sunHz),
          'sunFrac': pick(s.sunFrac),
          'earthAz': pick(s.earthAz),
          'earthEl': pick(s.earthEl),
          'earthHz': pick(s.earthHz),
          'earthFrac': pick(s.earthFrac),
          'power': pick(s.power),
          'dsn': [for (final i in idx) s.dsn[i]],
          'flags': [for (final i in idx) s.flags[i]],
        },
        'metrics': metricsJson(m),
        'goodWindows': [for (final w in goodWindows(s)) w.toJson()],
        'nextStretchFromMs': c.t0 + 10 * day,
        'nextStretch': ns == null ? null : {'window': ns.window.toJson(), 'good': ns.good},
        'daily': [
          for (final d in days) {'day': dayIso(d.day), 'sun': d.sun, 'earth': d.earth, 'both': d.both, 'cls': d.cls.name}
        ],
        'monthly': [
          for (final mc in monthlyCounts(days))
            {
              'year': mc.year,
              'month': mc.month,
              'days': mc.days,
              'counts': {for (final e in mc.counts.entries) e.key.name: e.value},
            }
        ],
        'goals': goals,
      };
    }
    out['rank'] = {
      for (final g in Goal.values)
        g.name: [
          for (final r in rank(metricsByCase, weightsFor(g))) {'case': r.id, 'siteId': r.name, 'total': r.score.total}
        ]
    };
    // longestGapPerWindow / slidingMin on fixed pseudo-random input
    final rnd = math.Random(20261012);
    final flags = Uint8List.fromList([for (var i = 0; i < 200; i++) rnd.nextInt(8)]);
    final vals = Float64List.fromList([for (var i = 0; i < 200; i++) rnd.nextDouble() * 10 - 5]);
    out['windowFunctions'] = {
      'flags': flags.toList(),
      'values': vals.toList(),
      'gap': {
        for (final bit in const [1, 2, 4])
          '$bit': {for (final m in const [1, 5, 37, 200, 201]) '$m': longestGapPerWindow(flags, 200, bit, m).toList()}
      },
      'slidingMin': {for (final m in const [1, 5, 37, 200, 201]) '$m': slidingMin(vals, 200, m).toList()},
    };
    out['customCoarse'] = {
      'lat': customLat,
      'lon': customLon,
      'siteHeightM': coarse.siteHeightM,
      'azStepDeg': coarse.masks[2.0]!.azStepDeg,
      'masks': {for (final e in coarse.masks.entries) '${e.key}': e.value.elevDeg.toList()},
    };
    File('$outDir/golden_plan.dart.json').writeAsStringSync(encode(out));
  });

  test('export golden_shadow', () {
    final epochs = {'2027-01-15T00:00:00Z': ms(2027, 1, 15), '2027-07-01T12:00:00Z': ms(2027, 7, 1, 12)};
    Map<String, dynamic> gridJson(ShadowGrid g) {
      final px = [
        [0, 0],
        [0, g.size - 1],
        [g.size - 1, 0],
        [g.size - 1, g.size - 1],
        [g.size ~/ 2, g.size ~/ 2],
        [g.size ~/ 3, (2 * g.size) ~/ 3],
        [(3 * g.size) ~/ 4, g.size ~/ 5],
        [g.size ~/ 2 - 7, g.size ~/ 2 + 11],
      ];
      var sum = 0.0;
      for (final v in g.z) {
        sum += v;
      }
      return {
        'size': g.size,
        'pxM': g.pxM,
        'pixels': [
          for (final p in px) {'row': p[0], 'col': p[1], 'z': g.z[p[0] * g.size + p[1]]}
        ],
        'zSum': sum,
      };
    }

    Map<String, dynamic> fieldJson(LightField f, {double? cr, double? cc, double? radius, bool full = false}) {
      final flags = f.packFlags(), shade = f.packShade();
      final counts = [0, 0, 0];
      for (final v in flags) {
        if (v & lightSunAny != 0) counts[0]++;
        if (v & lightSunFull != 0) counts[1]++;
        if (v & lightEarth != 0) counts[2]++;
      }
      var lsum = 0.0;
      for (final v in f.sunLambert) {
        lsum += v;
      }
      final sh = lightShares(flags, f.size, centreRow: cr, centreCol: cc, radius: radius);
      return {
        'size': f.size,
        'flagsGzB64': base64Encode(gzip.encode(flags)),
        'shadeGzB64': full ? base64Encode(gzip.encode(shade)) : null,
        'shadeB64Sha': base64Encode(shade), // replaced by its sha256 in post-processing
        'countSunAny': counts[0],
        'countSunFull': counts[1],
        'countEarth': counts[2],
        'lambertSum': lsum,
        'shares': {'sun': sh.sun, 'sunFull': sh.sunFull, 'earth': sh.earth, 'both': sh.both, 'inside': sh.inside},
      };
    }

    // the app's grids (AppState -> LightEngine.start -> LightGrids): the whole DEM, the
    // sweep lattice anchored to map.json dem.inner (80-90 S), the region view windowed to it
    final info = DemInfo.fromJson(mapMeta);
    final grids = LightGrids(dem.heights, dem.size, dem.scaleM, regionSizePx: info.innerSize);
    final region = grids.region;
    final fine = grids.fine;
    final regionWin = grids.regionWindow(region)!;
    final out = <String, dynamic>{
      'closeUpPx': closeUpPx,
      'closeUpRadiusM': closeUpRadiusM,
      'grids': {'region': gridJson(region), 'fine': gridJson(fine)},
      'region': <String, dynamic>{},
      'closeUp': <String, dynamic>{},
    };
    for (final e in epochs.entries) {
      final sun = eph.sun(e.value), earth = eph.earth(e.value);
      final f = computeLightField(region, sun, earth, window: regionWin);
      out['region'][e.key] = {
        'tMs': e.value,
        'window': {'r0': regionWin.r0, 'c0': regionWin.c0, 'size': regionWin.size},
        'originXM': (regionWin.c0 - region.size / 2) * region.pxM,
        'originYM': (region.size / 2 - regionWin.r0) * region.pxM,
        'sunBodyKm': [sun.x, sun.y, sun.z],
        'earthBodyKm': [earth.x, earth.y, earth.z],
        'field': fieldJson(f),
      };
    }
    final t = epochs.values.first;
    final sun = eph.sun(t), earth = eph.earth(t);
    final sr1 = catalog.byId('derosa2012-sr1-shackleton-rim');
    for (final (key, lat, lon, h) in [
      ('derosa2012-sr1-shackleton-rim', sr1.lat, sr1.lon, 2.0),
      ('custom', -85.98, -0.26, 10.0),
    ]) {
      final (row, col) = fine.pixelOf(lat, lon);
      final win = fine.windowAround(row, col, closeUpPx);
      final f = computeLightField(fine, sun, earth, window: win, observerHeightM: h);
      // light_engine _frame / LightFrame.pixelOf, same arithmetic
      final half = fine.size / 2;
      final x0M = (win.c0 - half) * fine.pxM, y0M = (half - win.r0) * fine.pxM;
      final (fx, fy) = latLonToXY(lat, lon);
      final fr = (y0M - fy) / fine.pxM - 0.5, fc = (fx - x0M) / fine.pxM - 0.5;
      out['closeUp'][key] = {
        'lat': lat,
        'lon': lon,
        'observerHeightM': h,
        'tMs': t,
        'sunBodyKm': [sun.x, sun.y, sun.z],
        'earthBodyKm': [earth.x, earth.y, earth.z],
        'pixel': [row, col],
        'window': {'r0': win.r0, 'c0': win.c0, 'size': win.size},
        'discRadiusPx': closeUpRadiusM / fine.pxM,
        'originXM': x0M,
        'originYM': y0M,
        'framePixel': [fr, fc],
        'field': fieldJson(f, cr: fr, cc: fc, radius: closeUpRadiusM / fine.pxM, full: true),
      };
    }
    File('$outDir/golden_shadow.dart.json').writeAsStringSync(encode(out));
  }, timeout: const Timeout(Duration(minutes: 10)));
}
